try (Recording recording = new Recording()) {
    recording.setName("diagnoza-incydentu");
    recording.enable("jdk.CPULoad").withPeriod(Duration.ofSeconds(1));
    recording.start();
    Thread.sleep(30_000); // nagrywanie w tle przez 30 sekund
    recording.stop();
    recording.dump(Path.of("nagranie.jfr"));
}

// PROBLEMATYCZNE: profile.jfc jako STALA konfiguracja produkcyjna
jcmd <pid> JFR.start name=stale settings=profile maxage=24h
// wysoki, CIAGLY narzut - profile.jfc jest przeznaczony do KROTKICH, celowanych analiz

// POPRAWNIE: default.jfc na stale, profile.jfc TYLKO na czas dochodzenia
jcmd <pid> JFR.start name=ciagle settings=default maxage=1h  // stale, niski narzut
// w razie potrzeby GLEBSZEJ analizy - osobna, KROTKA sesja profile:
jcmd <pid> JFR.start name=glebsza settings=profile maxage=5m

